const escapeHtml = (value) => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;')
function shell({ title, description, path, body, schema = null, keywords = 'GA4, Google Tag Manager, measurement, tracking, analytics' }) {
  const json = schema ? `<script type="application/ld+json">${JSON.stringify(schema)}</script>` : ''
  return `<!doctype html><html lang="en"><head><meta charset="UTF-8" /><meta name="viewport" content="width=device-width, initial-scale=1.0" /><meta name="theme-color" content="#07183f" /><meta name="description" content="${escapeHtml(description)}" /><meta name="keywords" content="${escapeHtml(keywords)}" /><meta name="robots" content="index,follow" /><meta property="og:type" content="website" /><meta property="og:site_name" content="Fixify" /><meta property="og:title" content="${escapeHtml(title)}" /><meta property="og:description" content="${escapeHtml(description)}" /><meta name="twitter:card" content="summary" /><meta name="twitter:title" content="${escapeHtml(title)}" /><meta name="twitter:description" content="${escapeHtml(description)}" /><link rel="icon" type="image/png" href="/favicon.png" /><link rel="preconnect" href="https://fonts.googleapis.com" /><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin /><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet" />${json}<title>${escapeHtml(title)}</title></head><body><div id="root"><main class="seo-shell"><p class="seo-kicker">Fixify measurement services</p>${body}<nav aria-label="Primary navigation"><a href="/services/">Services</a><a href="/case-studies/">Case Studies</a><a href="/approach/">Approach</a><a href="/pricing/">Pricing</a><a href="/guides/">Resources</a><a href="/about/">About</a><a href="/contact/?type=diagnostic">Request a diagnostic</a></nav></main></div><script type="module" src="/src/main.tsx"></script></body></html>`
}
function writePage(path, html) { const file = join(path, 'index.html'); mkdirSync(dirname(file), { recursive: true }); writeFileSync(file, html) }


